insert into public.toolbox_talks (issue, issue_date, send_at, month_theme, title, story_title, crew_question, ghl_template_id) values
  (1, '2027-01-04', '2027-01-03 19:59:00+00', 'Hazardous Energy', 'Prove the Power Is Off (LOTO try-out)', 'The label was wrong', 'A coworker went home with their lock still on the machine. Who can take it off?', '6ae6cc5fa92b4f00e1650ac4'),
  (2, '2027-01-11', '2027-01-10 19:59:00+00', 'Hazardous Energy', 'Locked Out Isn’t Empty: Release the Stored Energy', 'The ram that drifted', 'The press is locked out and the disconnect is off, but the ram is still up. Is it safe to reach under it for a quick look?', '6ae790d896c503e784057b93'),
  (3, '2027-01-18', '2027-01-17 19:59:00+00', 'Hazardous Energy', 'Many Hands, One Machine: Group Lockout and Shift Change', 'The lock that wasn’t on the box', 'Five mechanics are working on one line under a group lockbox. One says, “The lead’s lock is on the box, so I don’t need mine.” Is that right?', '6ae79107050bd1f5c11f81a9'),
  (4, '2027-01-25', '2027-01-24 19:59:00+00', 'Hazardous Energy', 'See a Lock, Leave It Alone: What Everyone Else Does During Lockout', 'The early start', 'Your machine is locked out, and the mechanic stepped away for parts. Your supervisor asks you to run one quick cycle to see if it’s fixed. What do you do?', '6ae7913096c503e7840587cc'),
  (5, '2027-02-01', '2027-01-31 19:59:00+00', 'Chemicals', 'Read the Label Before You Open It', 'The faded drum', 'A drum’s label is torn and half the words are gone. Everyone knows what’s in it. Can you keep using it?', '6ae7915bc3b3bfb3ee5a2ad4'),
  (6, '2027-02-08', '2027-02-07 19:59:00+00', 'Chemicals', 'Find the Safety Data Sheet Before You Need It', 'The sheet nobody could open', 'The power goes out during a chemical spill, and your SDSs are only on the computer. Is that OK, since the SDSs are “on file”?', '6ae791840cbc021f07addff2'),
  (7, '2027-02-15', '2027-02-14 19:59:00+00', 'Chemicals', 'Label the Spray Bottle Too', 'The bottle on the cart', 'You pour degreaser into a spray bottle and use some of it. Your shift is over, and the next shift wants the rest. Does it need a label?', '6ae791ada92b4f00e1719b3a'),
  (8, '2027-02-22', '2027-02-21 19:59:00+00', 'Chemicals', 'Chemical Splash? Get to the Eyewash Fast', 'The cart in front of the eyewash', 'A coworker gets a chemical splash in the eye. After a minute at the eyewash, they say it feels fine and want to get back to work. What do you do?', '6ae791d8a92b4f00e1719eb2'),
  (9, '2027-03-01', '2027-02-28 19:59:00+00', 'Machine Guarding', 'Know Every Danger Zone on Your Machine', 'The gap under the guard', 'The guard is on the machine, but there is a gap under it wide enough for your fingers to reach the blade. Is the machine guarded?', '6ae79200050bd1f5c11f9491'),
  (10, '2027-03-08', '2027-03-07 19:59:00+00', 'Machine Guarding', 'Never Remove or Bypass a Guard', 'The taped switch', 'The guard door interlock keeps stopping the line. A coworker says you can tape the switch for the rest of the shift. Is that OK?', '6ae7922a79173350f13b8b1f'),
  (11, '2027-03-15', '2027-03-14 18:59:00+00', 'Machine Guarding', 'Rotating Parts: Gloves Off, Sleeves Tight, Hair Up', 'The cuff at the drill press', 'You are drilling a small part that gets hot and has sharp edges. Can you wear gloves at the drill press?', '6ae7925496c503e78405a410'),
  (12, '2027-03-22', '2027-03-21 18:59:00+00', 'Machine Guarding', 'Bench Grinder Check: Mind the Gaps', 'The gap that grew', 'The grinder wheel has worn down and the tool rest gap looks wide. Can you slide the rest in while the wheel is spinning to save time?', '6ae7927f79173350f13b9287'),
  (13, '2027-03-29', '2027-03-28 18:59:00+00', 'Machine Guarding', 'Keep Your Hands Out: Push Sticks and Pinch Points', 'The last short piece', 'A small scrap is stuck next to the table saw blade. The saw is off but still coasting down. Can you flick it out with a push stick?', '6ae792a70cbc021f07ae007d'),
  (14, '2027-04-05', '2027-04-04 18:59:00+00', 'Respiratory & Eye Protection', 'Before You Wear a Respirator: Medical, Fit Test, Training', 'The spare in the cabinet', 'You were fit tested on a medium half-mask. The crib only has larges today. Can you wear a large?', '6ae792d202316e72fdd1dd22'),
  (15, '2027-04-12', '2027-04-11 18:59:00+00', 'Respiratory & Eye Protection', 'Check the Seal Every Time You Put It On', 'The torn flap', 'A coworker grew a short beard over vacation. His half-mask seems to pass the seal check. Can he wear it?', '6ae792fca92b4f00e171bb63'),
  (16, '2027-04-19', '2027-04-18 18:59:00+00', 'Respiratory & Eye Protection', 'Change Cartridges on Schedule and Store the Mask Right', 'The faint smell', 'Your vapor cartridges are not due for a change until tomorrow, but you start to smell solvent today. Can you finish the job first?', '6ae7932680bccb24ecfc6549'),
  (17, '2027-04-26', '2027-04-25 18:59:00+00', 'Respiratory & Eye Protection', 'Right Eyewear for the Hazard', 'The shield with nothing under it', 'You wear regular prescription glasses. Are they enough eye protection when you are cutting metal with a chop saw?', '6ae7935080bccb24ecfc68fb'),
  (18, '2027-05-03', '2027-05-02 18:59:00+00', 'Falls', 'Check the Ladder Before You Climb', 'The ladder in the corner', 'The stepladder is just a little too short. Is it OK to stand on the top step “just for a second”?', '6ae75539050bd1f5c11a7e2c'),
  (19, '2027-05-10', '2027-05-09 18:59:00+00', 'Falls', 'Four Feet Is the Line: Guard Every Edge and Hole', 'The grate that was open “just for a minute”', 'Is a plastic skylight dome strong enough to keep someone from falling through?', '6ae755700cbc021f07a8d297'),
  (20, '2027-05-17', '2027-05-16 18:59:00+00', 'Falls', 'Same-Level Falls: Spills, Cords and Clutter', 'The drip under the press', 'Who is responsible for a spill you did not make?', '6ae7559102316e72fdcc9f28'),
  (21, '2027-05-24', '2027-05-23 18:59:00+00', 'Falls', 'Harness Check: Inspect It Before You Trust It', 'The lanyard that had already done its job', 'You are 8 feet up, and your 6-foot lanyard is clipped to an anchor at your feet. Are you protected?', '6ae755bc0cbc021f07a8d730'),
  (22, '2027-05-31', '2027-05-30 18:59:00+00', 'Falls', 'After the Fall: Have a Rescue Plan', 'Twenty minutes is a long time', 'A coworker is hanging in his harness after a fall. He says he feels fine. How fast does he need to come down?', '6ae755e0050bd1f5c11a8a8e'),
  (23, '2027-06-07', '2027-06-06 18:59:00+00', 'Heat', 'Heat Stroke Is a 911 Call', 'He said he was fine', 'A coworker is sweating heavily and feels dizzy, but is talking normally. Is it time to call 911?', '6ae7560c02316e72fdccaa98'),
  (24, '2027-06-14', '2027-06-13 18:59:00+00', 'Heat', 'New to the Heat? Ease In', 'Second day on the dock', 'Your best worker just came back from two weeks of vacation somewhere cooler. Do they need to ramp up?', '6ae7562e0cbc021f07a8e1f2'),
  (25, '2027-06-21', '2027-06-20 18:59:00+00', 'Heat', 'Water. Rest. Shade. Indoors Too.', 'The quiet corner by the oven', 'On a hot shift, is a sports drink better than water?', '6ae7565979173350f13667e0'),
  (26, '2027-06-28', '2027-06-27 18:59:00+00', 'Heat', 'Make Your Heat Plan Before the Heat Wave', 'The address nobody knew', 'The thermometer says 82°F. Can it still be a dangerous heat day?', '6ae7567b79173350f1366ad7'),
  (27, '2027-07-05', '2027-07-04 18:59:00+00', 'Forklifts', 'Check the Truck Before the Shift', '“It always pulls a little”', 'The horn on the only available forklift does not work, and the load is urgent. What do you do?', '6ae756a50eb0e74ae0775ad3'),
  (28, '2027-07-12', '2027-07-11 18:59:00+00', 'Forklifts', 'People on Foot and Forklifts: See, Slow, Stay Clear', 'The blind corner by receiving', 'A forklift driver stops to talk with you. Where should you stand?', '6ae756c896c503e78400b245'),
  (29, '2027-07-19', '2027-07-18 18:59:00+00', 'Forklifts', 'Loads, Ramps and Tip-Overs', 'The turn on the ramp', 'You drive a stand-up reach truck with a rear entry, and it starts to tip. Do you stay in it?', '6ae756f202316e72fdccc0e4'),
  (30, '2027-07-26', '2027-07-25 18:59:00+00', 'Forklifts', 'Trained, Evaluated and Re-checked', 'Just one pallet', 'You were trained on a sit-down forklift. Can you drive the new stand-up reach truck today?', '6ae7571496c503e78400baf8'),
  (31, '2027-08-02', '2027-08-01 18:59:00+00', 'Electrical', 'Check the Cord Before You Plug It In', 'The cord with the black tape', 'The round ground pin snapped off an extension cord, but the tool still runs fine. Can you keep using it until the end of the shift?', '6ae7937b96c503e78405bdcd'),
  (32, '2027-08-09', '2027-08-08 18:59:00+00', 'Electrical', 'Keep the Space in Front of Every Panel Clear', 'The panel behind the boxes', 'The aisle is full, and you need to park a pallet jack for an hour. The only open spot is in front of the electrical panel. Is that OK?', '6ae793a6a92b4f00e171cec0'),
  (33, '2027-08-16', '2027-08-15 18:59:00+00', 'Electrical', 'Water and Power: Let the GFCI Do Its Job', 'The washer that kept tripping', 'The GFCI cord keeps tripping when you start the pressure washer. The wall outlet next to it has no GFCI. Can you plug in there to finish the job?', '6ae793cf0cbc021f07ae1f56'),
  (34, '2027-08-23', '2027-08-22 18:59:00+00', 'Electrical', 'Not Qualified? Stop, Stay Back and Report', 'The cover on the floor', 'A breaker tripped, and your line is down. The panel is right there, and the breaker is easy to reach. Can you flip it back on?', '6ae790db96c503e784057c11'),
  (35, '2027-08-30', '2027-08-29 18:59:00+00', 'Electrical', 'Someone Is Being Shocked: Don’t Touch, Cut the Power, Call 911', 'The power strip under the bench', 'A coworker is frozen on a drill cord, shaking, and can’t let go. What is the first thing you do?', '6ae7910879173350f13b6f64'),
  (36, '2027-09-06', '2027-09-05 18:59:00+00', 'Emergency Action', 'Know Your Emergency Plan Before the Alarm', 'The new hire and the horn', 'An alarm goes off with a tone you have never heard before. Nobody near you is sure what it means. What do you do?', '6ae791300cbc021f07add9f2'),
  (37, '2027-09-13', '2027-09-12 18:59:00+00', 'Emergency Action', 'Exit Routes Stay Clear and Unlocked', 'The pallet by the side door', 'Night shift chains the side exit door after 10 p.m. to stop theft, but the main door stays open. Is that OK?', '6ae79157050bd1f5c11f87bc'),
  (38, '2027-09-20', '2027-09-19 18:59:00+00', 'Emergency Action', 'Get Out, Go to Your Spot, Get Counted', 'The truck in the lot', 'You reach the assembly point and realize a coworker from your line is not there. Do you go back in to find them?', '6ae7918002316e72fdd1bfae'),
  (39, '2027-09-27', '2027-09-26 18:59:00+00', 'Emergency Action', 'When Leaving Isn’t Safe: Know Where to Shelter', 'The break room with the glass wall', 'A tornado warning siren sounds while you are on the loading dock. Do you head for the outdoor assembly point?', '6ae791a80eb0e74ae07c4fc6'),
  (40, '2027-10-04', '2027-10-03 18:59:00+00', 'Fire Prevention', 'Clear the Fuel: Clutter, Oily Rags and Dust', 'The rag in the trash can', 'Dust has built up on top of the beams. The fastest fix is to blow it down with the air hose. Good idea?', '6ae791d2a92b4f00e1719e38'),
  (41, '2027-10-11', '2027-10-10 18:59:00+00', 'Fire Prevention', 'Fire Extinguishers: Know When Not to Fight a Fire', 'The fire between him and the door', 'Your site’s plan says evacuate only, but there is an extinguisher on the wall right next to a small trash-can fire. Do you use it?', '6ae791fb050bd1f5c11f941f'),
  (42, '2027-10-18', '2027-10-17 18:59:00+00', 'Fire Prevention', 'Hot Work: Get the Permit, Keep the Fire Watch', 'The smell after lunch', 'The welder is almost done, and the fire watch is asked to go help unload a truck “for just a few minutes.” OK?', '6ae79229050bd1f5c11f99f8'),
  (43, '2027-10-25', '2027-10-24 18:59:00+00', 'Fire Prevention', 'Flammable Liquids: Right Can, Lid Shut, Back in the Cabinet', 'The coffee cup of solvent', 'The flammable cabinet is full. Can the extra cans sit on top of the cabinet until there is room?', '6ae792540cbc021f07adf872'),
  (44, '2027-11-01', '2027-10-31 18:59:00+00', 'Lifting & Driving', 'Plan the Lift Before You Pick It Up', 'The box that looked light', 'A heavy, awkward part needs to move and your coworker offers to help. You both grab an end. What has to happen before anyone lifts?', '6ae7927cc3b3bfb3ee5a46c9'),
  (45, '2027-11-08', '2027-11-07 19:59:00+00', 'Lifting & Driving', 'Report the Ache Before It Becomes an Injury', 'The tingling at the end of the shift', 'Your wrist has ached at the end of every shift this week, but it feels fine by morning. Should you report it?', '6ae792aa69ea1decf814a0c6'),
  (46, '2027-11-15', '2027-11-14 19:59:00+00', 'Lifting & Driving', 'Push, Don’t Pull: Carts and Hand Pallet Jacks', 'The wheel that would not turn', 'The loaded cart is stacked so high you cannot see over it. Is it OK to turn around and pull it so you can see where you are going?', '6ae792d2c3b3bfb3ee5a4d23'),
  (47, '2027-11-22', '2027-11-21 19:59:00+00', 'Lifting & Driving', 'Holiday Driving: Rested, Buckled and Phone Down', 'The last ten minutes', 'You are driving home after a double shift and feel your car drift toward the lane line. You are only ten minutes from home. Push through or pull over?', '6ae792fc80bccb24ecfc614e'),
  (48, '2027-11-29', '2027-11-28 19:59:00+00', 'Lifting & Driving', 'Company Vehicles: Walk Around, Then Back Up With a Spotter', 'The pallet behind the van', 'You are backing a truck to the dock with a spotter guiding you. The spotter suddenly steps out of your mirror. What do you do?', '6ae7932a80bccb24ecfc65a8'),
  (49, '2027-12-06', '2027-12-05 19:59:00+00', 'Winter Safety', 'Cold Stress: Know the Signs of Hypothermia and Frostbite', 'The gloves that stayed wet', 'A coworker’s fingers are white and numb after an hour on the dock. Someone says to rub them hard or hold them over the heater. Right?', '6ae793530cbc021f07ae0e66'),
  (50, '2027-12-13', '2027-12-12 19:59:00+00', 'Winter Safety', 'Icy Lots and Entrances: Short Steps and Three Points', 'The step off the truck', 'You are climbing down from the forklift, and it is only a short drop. Is it OK to just hop down?', '6ae7937c79173350f13ba830'),
  (51, '2027-12-20', '2027-12-19 19:59:00+00', 'Winter Safety', 'Carbon Monoxide: Keep Engines Out and Alarms On', 'Headaches in the back room', 'It is freezing out, so the crew wants to run the gas generator just inside the big door, with the door half open. Is that OK?', '6ae793ac0eb0e74ae07c84ec'),
  (52, '2027-12-27', '2027-12-26 19:59:00+00', 'Winter Safety', 'Tired and Short-Staffed: Don’t Skip Steps', 'The last order before the holiday', 'It is the last hour of a double shift, and you notice you have read the same work order three times. What do you do?', '6ae793d60eb0e74ae07c8891')
